/* Momo Kids Lab background music: plays the playlist in order, then repeats it. */
(function () {
  'use strict';
  if (document.getElementById('momo-music-toggle')) return;
  var language = document.querySelector('#site-language');
  if (!language) return;
  var picker = language.closest('.language-picker');
  if (!picker) return;
  var labels = {
    en: {play:'Play background music', mute:'Mute background music', error:'Music could not start. Please press Play to try again.'},
    es: {play:'Reproducir música de fondo', mute:'Silenciar música de fondo', error:'No se pudo iniciar la música. Pulsa reproducir para volver a intentarlo.'},
    th: {play:'เปิดเพลงประกอบ', mute:'ปิดเสียงเพลงประกอบ', error:'ไม่สามารถเปิดเพลงได้ โปรดกดเล่นเพื่อลองอีกครั้ง'},
    'zh-CN': {play:'播放背景音乐', mute:'静音背景音乐', error:'音乐无法播放，请再次点击播放。'}
  };
  var style = document.createElement('style');
  style.textContent = `.nav-audio-controls{display:flex;align-items:center;gap:8px;flex-shrink:0}.nav-audio-controls .language-picker{margin-left:0}.momo-music-toggle{display:block;flex:0 0 64px;width:64px;height:54.45px;min-width:44px;min-height:44px;padding:0;border:0;border-radius:50%;background-color:transparent;background-image:url("data:image/webp;base64,");background-repeat:no-repeat;background-size:200% 100%;background-position:right center;cursor:pointer;transition:transform .15s ease,filter .15s ease}.momo-music-toggle[data-playing="true"]{background-position:left center}.momo-music-toggle:hover{filter:brightness(1.06);transform:translateY(-2px)}.momo-music-toggle:active{transform:translateY(1px) scale(.97)}.momo-music-toggle:focus-visible{outline:3px solid #164C80;outline-offset:3px}.momo-music-status{position:absolute;width:1px;height:1px;padding:0;margin:-1px;overflow:hidden;clip:rect(0,0,0,0);white-space:nowrap;border:0}@media(max-width:1100px){.nav-audio-controls{margin-left:auto}}@media(max-width:480px){.nav-audio-controls{gap:5px}.momo-music-toggle{flex-basis:56px;width:56px;height:47.64px}}@media(prefers-reduced-motion:reduce){.momo-music-toggle{transition:none}.momo-music-toggle:hover,.momo-music-toggle:active{transform:none}}`;
  document.head.appendChild(style);
  var group = document.createElement('div');
  group.className = 'nav-audio-controls';
  picker.parentNode.insertBefore(group, picker);
  group.appendChild(picker);
  var button = document.createElement('button');
  button.id = 'momo-music-toggle';
  button.className = 'momo-music-toggle';
  button.type = 'button';
  button.setAttribute('aria-pressed','false');
  button.dataset.playing = 'false';
  group.appendChild(button);
  var status = document.createElement('span');
  status.className = 'momo-music-status';
  status.setAttribute('role','status');
  status.setAttribute('aria-live','polite');
  group.appendChild(status);
  var music = document.createElement('audio');
  music.id = 'momo-background-music';
  var playlist = ['assets/audio/momo-happy-little-universe.mp3', 'assets/audio/momo-theme.mp3'];
  var track = 0;
  music.src = playlist[track];
  music.preload = 'auto';
  music.autoplay = true;
  music.loop = false;
  music.volume = 0.25;
  music.muted = false;
  music.setAttribute('aria-hidden','true');
  document.body.appendChild(music);
  var busy = false;
  // When a song ends, start the next one; after the last song, go back to the first.
  music.addEventListener('ended',function(){
    track = (track + 1) % playlist.length;
    music.src = playlist[track];
    music.play().catch(function(){ music.muted = true; music.pause(); render(); });
  });
  function copy(){ return labels[language.value] || labels.en; }
  function render(){
    var playing = !music.paused && !music.muted;
    button.dataset.playing = String(playing);
    button.setAttribute('aria-pressed',String(playing));
    button.setAttribute('aria-label',playing ? copy().mute : copy().play);
    button.title = playing ? copy().mute : copy().play;
  }
  button.addEventListener('click',async function(){
    if(busy) return;
    status.textContent = '';
    if(!music.paused && !music.muted){ music.muted=true; music.pause(); render(); return; }
    busy=true;
    try{music.muted=false; await music.play();}
    catch(error){music.muted=true; music.pause();status.textContent=copy().error;}
    finally{busy=false;render();}
  });
  ['play','pause','volumechange'].forEach(function(event){music.addEventListener(event,render);});
  music.addEventListener('error',function(){music.pause();music.muted=true;status.textContent=copy().error;render();});
  language.addEventListener('change',render);
  new MutationObserver(render).observe(document.documentElement,{attributes:true,attributeFilter:['lang']});
  window.addEventListener('pagehide',function(){music.muted=true;music.pause();render();});
  render();
  // Try audible autoplay; keep the control truthful if the browser blocks it.
  busy = true;
  music.play().catch(function(){
    music.muted = true;
    music.pause();
  }).finally(function(){
    busy = false;
    render();
  });
})();
